// RSS and Atom feeds, read by the "Read feeds" node.
const settings = $('Watch settings').first().json;
// The Code node sandbox has no URLSearchParams.
const toQuery = (params) =>
  Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join('&');
const sources = [];

for (const category of settings.arxivCategories) {
  sources.push({
    source: `arXiv ${category}`,
    type: 'paper',
    url: `https://rss.arxiv.org/rss/${category}`,
    filtered: true,
    maxAgeDays: settings.limits.paperMaxAgeDays,
  });
}

const arxivQuery = toQuery({
  search_query: settings.arxivSearch,
  sortBy: 'submittedDate',
  sortOrder: 'descending',
  max_results: '50',
});
sources.push({
  source: 'arXiv search',
  type: 'paper',
  url: `https://export.arxiv.org/api/query?${arxivQuery}`,
  filtered: true,
  maxAgeDays: settings.limits.paperMaxAgeDays,
});

for (const repository of settings.githubReleases) {
  sources.push({
    source: `GitHub ${repository}`,
    type: 'release',
    url: `https://github.com/${repository}/releases.atom`,
    filtered: false,
    maxAgeDays: settings.limits.releaseMaxAgeDays,
  });
}

return sources.map((json) => ({ json }));

// Turns every feed entry into a common entry shape.
const clean = (text) =>
  String(text ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const authorsOf = (entry) => {
  const author = entry.creator ?? entry.author ?? entry['dc:creator'];
  if (Array.isArray(author)) return author.map((a) => a?.name ?? a).join(', ');
  return clean(author?.name ?? author);
};

const entries = [];
$input.all().forEach((item, index) => {
  const entry = item.json;
  if (entry.error || !entry.link) return;
  const source = $('List feeds').itemMatching(index).json;
  entries.push({
    source: source.source,
    type: source.type,
    filtered: source.filtered,
    maxAgeDays: source.maxAgeDays,
    title: clean(entry.title),
    url: entry.link,
    authors: authorsOf(entry),
    summary: clean(entry.contentSnippet ?? entry.content ?? entry.summary).replace(
      /^arXiv:\S+ Announce Type: \S+ Abstract: /,
      '',
    ),
    published: entry.isoDate ?? entry.pubDate ?? null,
  });
});

return entries.map((json) => ({ json }));

// JSON APIs, called by the "Call APIs" node.
const settings = $('Watch settings').first().json;
// The Code node sandbox has no URLSearchParams.
const toQuery = (params) =>
  Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join('&');
const daysAgo = (days) => new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
const sources = [];

for (const search of settings.githubSearches) {
  const query = toQuery({
    q: `${search} in:name,description,topics created:>=${daysAgo(settings.limits.repositoryMaxAgeDays)}`,
    sort: 'updated',
    per_page: '30',
  });
  sources.push({
    api: 'github',
    source: 'GitHub search',
    type: 'repository',
    url: `https://api.github.com/search/repositories?${query}`,
    filtered: true,
    maxAgeDays: settings.limits.repositoryMaxAgeDays + 1,
  });
}

// One OpenAlex call for every search ("|" means OR): OpenAlex answers 429 to close calls.
const openAlexQuery = toQuery({
  filter: `title_and_abstract.search:${settings.openAlexSearches.join('|')},from_publication_date:${daysAgo(settings.limits.openAlexLookbackDays)}`,
  sort: 'publication_date:desc',
  'per-page': '100',
  select: 'id,doi,type,display_name,publication_date,authorships,abstract_inverted_index,primary_location',
});
sources.push({
  api: 'openalex',
  source: 'OpenAlex',
  type: 'paper',
  url: `https://api.openalex.org/works?${openAlexQuery}`,
  filtered: true,
  maxAgeDays: null,
});

return sources.map((json) => ({ json }));

// Turns GitHub search and OpenAlex results into a common entry shape.
const clean = (text) =>
  String(text ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

// OpenAlex ships abstracts as an inverted index: { word: [positions] }.
const abstractOf = (index) => {
  if (!index) return '';
  const words = [];
  for (const [word, positions] of Object.entries(index)) {
    for (const position of positions) words[position] = word;
  }
  return words.filter(Boolean).join(' ');
};

const entries = [];
$input.all().forEach((item, index) => {
  const response = item.json;
  if (response.error) return;
  const source = $('List APIs').itemMatching(index).json;
  const base = {
    source: source.source,
    type: source.type,
    filtered: source.filtered,
    maxAgeDays: source.maxAgeDays,
  };

  if (source.api === 'github') {
    for (const repository of response.items ?? []) {
      entries.push({
        ...base,
        title: repository.full_name,
        url: repository.html_url,
        authors: repository.owner?.login ?? '',
        summary: clean(
          [repository.description, repository.language, `${repository.stargazers_count} stars`]
            .filter(Boolean)
            .join(' · '),
        ),
        published: repository.created_at,
      });
    }
  }

  if (source.api === 'openalex') {
    for (const work of response.results ?? []) {
      // Datasets and supplementary material duplicate the paper they belong to.
      if (['dataset', 'paratext', 'erratum'].includes(work.type)) continue;
      entries.push({
        ...base,
        title: clean(work.display_name),
        url: work.doi ?? work.primary_location?.landing_page_url ?? work.id,
        authors: (work.authorships ?? [])
          .slice(0, 5)
          .map((authorship) => authorship.author?.display_name)
          .filter(Boolean)
          .join(', '),
        summary: clean(abstractOf(work.abstract_inverted_index)),
        published: work.publication_date,
      });
    }
  }
});

return entries.map((json) => ({ json }));

// Keeps fresh entries that match the keywords, without duplicates inside this run.
const settings = $('Watch settings').first().json;
const escape = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const matcher = (keyword) => new RegExp(`\\b${escape(keyword.toLowerCase())}\\b`, 'i');
const compile = (keywords) => keywords.map((keyword) => [keyword, matcher(keyword)]);
const core = compile(settings.keywords.core);
const related = compile(settings.keywords.related);
const boost = compile(settings.keywords.boost);
const matches = (list, text) => list.filter(([, regex]) => regex.test(text)).map(([keyword]) => keyword);

// Force HTTPS and drop the arXiv version suffix.
const canonical = (url) =>
  String(url)
    .trim()
    .replace(/^http:\/\//, 'https://')
    .replace(/(arxiv\.org\/abs\/[^v\s]+)v\d+$/, '$1');

// The same paper comes from arXiv and OpenAlex with two URLs, so papers are keyed by title.
const keyOf = (entry, url) =>
  entry.type === 'paper' ? `paper:${entry.title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim()}` : url;

const now = Date.now();
const seen = new Set();
const latestRelease = new Map();
const kept = [];

for (const { json: entry } of $input.all()) {
  if (!entry.url || !entry.title) continue;
  const url = canonical(entry.url);
  const key = keyOf(entry, url);
  if (seen.has(key)) continue;
  seen.add(key);

  const published = Date.parse(entry.published);
  if (entry.maxAgeDays && published && now - published > entry.maxAgeDays * 86400000) continue;

  let text = `${entry.title} ${entry.summary}`.toLowerCase();
  for (const excluded of settings.keywords.excluded) text = text.split(excluded.toLowerCase()).join(' ');
  const coreTags = matches(core, text);
  const relatedTags = matches(related, text);
  if (entry.filtered && !coreTags.length && !relatedTags.length) continue;

  const result = {
    key,
    source: entry.source,
    type: entry.type,
    title: entry.title,
    url,
    authors: entry.authors,
    summary: entry.summary,
    published: published ? new Date(published).toISOString() : null,
    tier: coreTags.length || !entry.filtered ? 'core' : 'related',
    tags: entry.type === 'release' ? ['release'] : [...coreTags, ...relatedTags],
    // Ranking only: climbing keywords count double, technical subjects once.
    score: entry.type === 'release' ? 3 : coreTags.length * 2 + relatedTags.length + matches(boost, text).length,
  };

  // A repository can publish several releases a day: only the newest one is posted.
  if (entry.type === 'release') {
    const previous = latestRelease.get(entry.source);
    if (previous && (Date.parse(previous.published) || 0) >= (published || 0)) continue;
    latestRelease.set(entry.source, result);
    continue;
  }
  kept.push(result);
}

return [...kept, ...latestRelease.values()].map((json) => ({ json }));

// Ranks the new entries and packs them into Discord messages.
// Discord limits: 10 embeds and 6000 embed characters per message.
const settings = $('Watch settings').first().json;
// "Skip already posted" always outputs an item, so an empty run still reports failed sources.
const entries = $input
  .all()
  .map((item) => item.json)
  .filter((entry) => entry.key);

// Sources that failed this morning (unreachable feed, API error...).
const failed = new Set();
for (const [fetchNode, listNode] of [
  ['Read feeds', 'List feeds'],
  ['Call APIs', 'List APIs'],
]) {
  const sources = $(listNode).all();
  for (const item of $(fetchNode).all()) {
    if (!item.json.error) continue;
    const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
    const source = sources[typeof paired === 'number' ? paired : (paired?.item ?? 0)]?.json;
    failed.add(source ? `${source.source} (${source.url.split('?')[0]})` : fetchNode);
  }
}
const byDate = (a, b) => (Date.parse(b.published) || 0) - (Date.parse(a.published) || 0);
// Releases of the monitored repositories are always posted (one per repository at most).
const releases = entries.filter((e) => e.type === 'release').sort(byDate);
const core = entries
  .filter((e) => e.tier === 'core' && e.type !== 'release')
  .sort((a, b) => b.score - a.score || byDate(a, b));
const related = entries.filter((e) => e.tier === 'related').sort(byDate);
const picked = [...core.slice(0, settings.limits.core), ...related.slice(0, settings.limits.related), ...releases];
const warning = failed.size ? `\n:warning: Sources en erreur : ${[...failed].join(', ')}` : '';
if (!picked.length) {
  return warning ? [{ json: { content: `**Veille technique** : aucune nouveauté.${warning}`.slice(0, 2000), embeds: [] } }] : [];
}

const cut = (text, max) => {
  const value = String(text ?? '').trim();
  return value.length > max ? `${value.slice(0, max - 1).trimEnd()}…` : value;
};
const colors = { paper: 0x5865f2, release: 0x57f287, repository: 0xfee75c };

const embeds = picked.map((entry) => {
  const embed = {
    title: cut(entry.title, 256),
    url: entry.url,
    color: colors[entry.type] ?? 0x99aab5,
    footer: { text: cut([entry.source, entry.tags.join(', ')].filter(Boolean).join(' · '), 200) },
  };
  if (entry.summary) embed.description = cut(entry.summary, 350);
  if (entry.authors) embed.author = { name: cut(entry.authors, 200) };
  if (entry.published) embed.timestamp = entry.published;
  return embed;
});

const size = (embed) =>
  embed.title.length + (embed.description?.length ?? 0) + (embed.author?.name.length ?? 0) + embed.footer.text.length;

const messages = [];
let current = [];
let currentSize = 0;
for (const embed of embeds) {
  if (current.length === 10 || currentSize + size(embed) > 5500) {
    messages.push(current);
    current = [];
    currentSize = 0;
  }
  current.push(embed);
  currentSize += size(embed);
}
messages.push(current);

const date = new Date().toLocaleDateString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long' });
const skipped = entries.length - picked.length;
const header =
  `**Veille technique du ${date}** : ${picked.length} nouveauté${picked.length > 1 ? 's' : ''}` +
  (skipped ? ` (${skipped} autre${skipped > 1 ? 's' : ''} non affichée${skipped > 1 ? 's' : ''})` : '') +
  warning;

return messages.map((chunk, index) => ({ json: { content: index === 0 ? header.slice(0, 2000) : '', embeds: chunk } }));
